cd /home/ahmoh/Documents/proj/demo/QuickFlow/frontend/src/app/features/habits && cat > habits-page.component.html <<'EOF'
<ui-page-header title="Habits" titleTestId="habits-title">
  <button actions mat-raised-button color="primary" type="button" data-testid="habits-add-button" (click)="openCreate()">
    Add habit
  </button>
</ui-page-header>

<ui-card class="toolbar-card">
  <section class="toolbar" aria-label="Habit filters">
    <mat-slide-toggle [formControl]="showInactive" data-testid="habits-show-inactive">Show inactive</mat-slide-toggle>
  </section>
</ui-card>

@if (loading()) {
  <div class="loading" data-testid="habits-loading">
    <ui-skeleton variant="card" [count]="3" />
  </div>
}

@if (loadFailed()) {
  <div class="error-state" role="alert" data-testid="habits-load-error">
    <span>Habits could not be loaded.</span>
    <button mat-stroked-button type="button" data-testid="habits-error-retry" (click)="load()">Retry</button>
  </div>
} @else if (!loading() && habits().length === 0) {
  <qf-empty-state
    testId="habits"
    illustration="habits"
    icon="↻"
    title="No habits yet"
    message="Add a habit to track what you do every day or every week."
    actionLabel="Add habit"
    (action)="openCreate()"
  />
}

<ul class="habit-grid">
  @for (habit of habits(); track habit.id) {
    <li>
      <ui-card
        class="habit-card"
        [interactive]="habit.active"
        [class.inactive]="!habit.active"
        [class.done]="habit.doneForCurrentPeriod"
        [attr.data-testid]="'habits-card-' + habit.id"
      >
        <div class="habit-main">
          <h2 class="habit-name qf-title">{{ habit.name }}</h2>
          @if (habit.description) {
            <p class="habit-description qf-body">{{ habit.description }}</p>
          }
          <div class="habit-tags">
            <span class="tag qf-label" [attr.data-testid]="'habits-frequency-' + habit.id">{{ frequencyLabel(habit) }}</span>
            @if (!habit.active) {
              <span class="tag qf-label" [attr.data-testid]="'habits-inactive-' + habit.id">Inactive</span>
            }
          </div>
        </div>

        <div class="habit-status">
          <span class="progress qf-label" [class.progress-done]="habit.doneForCurrentPeriod">
            @if (habit.doneForCurrentPeriod) {
              <mat-icon svgIcon="check" aria-hidden="true" />
            }
            <span [attr.data-testid]="'habits-progress-' + habit.id">{{ progressLabel(habit) }}</span>
          </span>
          <span class="streak qf-caption" [attr.data-testid]="'habits-streak-' + habit.id">{{ streakLabel(habit) }}</span>
        </div>

        <div class="habit-actions">
          <button
            mat-icon-button
            type="button"
            [attr.aria-label]="habit.doneForCurrentPeriod ? 'Undo completion' : 'Mark done'"
            [attr.title]="habit.doneForCurrentPeriod ? 'Undo' : 'Mark done'"
            [attr.data-testid]="'habits-toggle-' + habit.id"
            [disabled]="!habit.active"
            (click)="toggleCompletion(habit)"
          >
            <mat-icon svgIcon="check" aria-hidden="true" />
          </button>
          <button
            mat-icon-button
            type="button"
            aria-label="Edit habit"
            title="Edit"
            [attr.data-testid]="'habits-edit-' + habit.id"
            (click)="openEdit(habit)"
          >
            <mat-icon svgIcon="edit" aria-hidden="true" />
          </button>
          <button
            mat-icon-button
            type="button"
            [attr.aria-label]="habit.active ? 'Deactivate habit' : 'Activate habit'"
            [attr.title]="habit.active ? 'Deactivate' : 'Activate'"
            [attr.data-testid]="'habits-deactivate-' + habit.id"
            (click)="toggleActive(habit)"
          >
            <mat-icon [svgIcon]="habit.active ? 'archive' : 'unarchive'" aria-hidden="true" />
          </button>
          <button
            mat-icon-button
            color="warn"
            type="button"
            aria-label="Delete habit"
            title="Delete"
            [attr.data-testid]="'habits-delete-' + habit.id"
            (click)="confirmDelete(habit)"
          >
            <mat-icon svgIcon="delete" aria-hidden="true" />
          </button>
        </div>
      </ui-card>
    </li>
  }
</ul>
EOF
cat > habits-page.component.scss <<'EOF'
.toolbar-card {
  display: block;
  margin-bottom: var(--qf-space-4);
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--qf-space-3);
}

.loading {
  margin: var(--qf-space-4) 0;
}

// Responsive grid: as many 280 px cards as fit the row.
.habit-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--qf-space-4);
}

.habit-card {
  display: flex;
  flex-direction: column;
  gap: var(--qf-space-3);
  height: 100%;
  box-sizing: border-box;

  // Done for the current period: accent border.
  &.done {
    border-color: var(--qf-accent);
  }

  // Inactive habits are dimmed and cannot be marked done.
  &.inactive {
    opacity: 0.55;
  }
}

.habit-main {
  display: flex;
  flex-direction: column;
  gap: var(--qf-space-1);
  min-width: 0;
}

.habit-name {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--qf-text);
}

.habit-description {
  margin: 0;
  color: var(--qf-text-muted);
  overflow-wrap: anywhere;
}

.habit-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--qf-space-2);
  margin-top: var(--qf-space-1);
}

// Chip-like tag for frequency and inactive state.
.tag {
  padding: var(--qf-space-1) var(--qf-space-2);
  border: 1px solid var(--qf-outline);
  border-radius: var(--qf-radius-pill);
  color: var(--qf-text-muted);
}

.habit-status {
  display: flex;
  flex-direction: column;
  gap: var(--qf-space-1);
}

.progress {
  display: inline-flex;
  align-items: center;
  gap: var(--qf-space-1);
  color: var(--qf-text-muted);

  mat-icon {
    width: 18px;
    height: 18px;
    font-size: 18px;
  }

  &.progress-done {
    color: var(--qf-success);
  }
}

.streak {
  color: var(--qf-text-muted);
}

// Icon actions stay in one row; the row wraps only on very narrow cards.
.habit-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--qf-space-1);
  margin-top: auto;
}
EOF
